#include <stdio.h>
#include <stdlib.h>

int cmp_desc(const void *a, const void *b) {
    return (*(int *)b - *(int *)a);
}

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    int a[505];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    qsort(a, n, sizeof(int), cmp_desc);

    printf("%d\n", a[k - 1]);

    return 0;
}
